        'AWS WAF logging', 'https://docs.aws.amazon.com/waf/latest/developerguide/logging.html'),
    ('aws-waf', 'waf-logging-full-sem-filtro-de-campos',
        'AWS WAF pricing', 'https://aws.amazon.com/waf/pricing/'),
    ('aws-waf', 'waf-web-acls-sem-otimizacao-de-regras',
        'AWS WAF pricing', 'https://aws.amazon.com/waf/pricing/'),
    ('aws-waf', 'waf-web-acls-sem-otimizacao-de-regras',
        'AWS WAF developer guide', 'https://docs.aws.amazon.com/waf/latest/developerguide/waf-chapter.html'),
    ('nat-gateway', 'nat-gateway-por-az-sem-necessidade-de-alta-disponibilidade',
        'NAT gateway pricing', 'https://docs.aws.amazon.com/vpc/latest/userguide/nat-gateway-pricing.html'),
    ('nat-gateway', 'nat-gateway-por-az-sem-necessidade-de-alta-disponibilidade',
